prologue:
/* Память игры. Адрес всегда проверяется на принадлежность модулю: чужая память
   роняет процесс молча, а мод должен просто ничего не сделать */
static MOD_UNUSED int interop_inside(uintptr_t address) {
    uintptr_t base, size;
    if (API->interop == 0) return 0;
    base = API->interop->ModuleBase(SELF);
    size = API->interop->ModuleSize(SELF);
    return base != 0 && size != 0 && address >= base && address < base + size;
}

static MOD_UNUSED int interop_int(uintptr_t address) {
    int value = 0;
    if (!interop_inside(address)) return 0;
    if (API->interop->Read(SELF, address, &value, (uint32_t)sizeof value) == 0) return 0;
    return value;
}

static MOD_UNUSED float interop_float(uintptr_t address) {
    float value = 0.0f;
    if (!interop_inside(address)) return 0.0f;
    if (API->interop->Read(SELF, address, &value, (uint32_t)sizeof value) == 0) return 0.0f;
    return value;
}

static MOD_UNUSED void interop_write_int(uintptr_t address, int value) {
    if (interop_inside(address)) API->interop->Write(SELF, address, &value, (uint32_t)sizeof value);
}

static MOD_UNUSED void interop_write_float(uintptr_t address, float value) {
    if (interop_inside(address)) API->interop->Write(SELF, address, &value, (uint32_t)sizeof value);
}

/* "56 8B 74" — пробелы можно опускать; вопросительные знаки здесь не годятся */
static MOD_UNUSED int interop_bytes(const char* text, unsigned char* out, int room) {
    int count = 0, half = 0, value = 0;
    const char* at;
    for (at = text; *at != 0 && count < room; ++at) {
        int digit;
        if (*at == ' ' || *at == ',') continue;
        if (*at >= '0' && *at <= '9') digit = *at - '0';
        else if (*at >= 'a' && *at <= 'f') digit = *at - 'a' + 10;
        else if (*at >= 'A' && *at <= 'F') digit = *at - 'A' + 10;
        else return -1;
        value = value * 16 + digit;
        if (++half == 2) {
            out[count++] = (unsigned char)value;
            half = 0;
            value = 0;
        }
    }
    return half == 0 ? count : -1;
}

static MOD_UNUSED void interop_write_bytes(uintptr_t address, const char* text) {
    unsigned char bytes[64];
    const int count = interop_bytes(text, bytes, (int)sizeof bytes);
    if (count > 0 && interop_inside(address))
        API->interop->Write(SELF, address, bytes, (uint32_t)count);
}

static MOD_UNUSED int interop_bytes_are(uintptr_t address, const char* text) {
    unsigned char want[64], have[64];
    const int count = interop_bytes(text, want, (int)sizeof want);
    if (count <= 0 || !interop_inside(address)) return 0;
    if (API->interop->Read(SELF, address, have, (uint32_t)count) == 0) return 0;
    return memcmp(want, have, (size_t)count) == 0;
}

/* Заглушить код: 0x90 столько раз, сколько сказано */
static MOD_UNUSED void interop_nop(uintptr_t address, int count) {
    unsigned char bytes[64];
    int at;
    if (count <= 0 || count > (int)sizeof bytes || !interop_inside(address)) return;
    for (at = 0; at < count; ++at) bytes[at] = 0x90;
    API->interop->Write(SELF, address, bytes, (uint32_t)count);
}

/* Узор вида "56 8B 74 24 08 E8 ?? ?? ?? ??"; 0, если совпадений нет или их больше одного */
static MOD_UNUSED uintptr_t interop_find(const char* pattern) {
    uintptr_t address = 0;
    if (API->interop == 0) return 0;
    return API->interop->Find(SELF, pattern, &address) == AMOD_FIND_OK ? address : 0;
}
